// app.UseHsts();                        // 2. 安全头
// app.UseHttpsRedirection();            // 3. HTTPS
// app.UseRouting();                      // 4. 路由解析
// app.UseCors();                        // 5. CORS（路由后，认证前）
// app.UseAuthentication();              // 6. 认证（建立 User）
// app.UseAuthorization();               // 7. 授权（基于 User 决策）
// app.UseEndpoints(endpoints => ...);   // 8. 最后：执行端点
